#include <bits/stdc++.h>
using namespace std;

struct Line {
    long long m, b;

    long long eval(long long x) const {
        return m * x + b;
    }
};

struct CHT {
    deque<Line> hull;

    void add(Line line) {
        while (!hull.empty() && hull.back().m == line.m) {
            if (hull.back().b <= line.b) return;
            hull.pop_back();
        }

        while (hull.size() >= 2) {
            const Line &a = hull[hull.size() - 2];
            const Line &b = hull.back();
            if ((__int128)(b.b - a.b) * (b.m - line.m) >=
                (__int128)(line.b - b.b) * (a.m - b.m)) {
                hull.pop_back();
            } else {
                break;
            }
        }
        hull.push_back(line);
    }

    long long query(long long x) {
        while (hull.size() >= 2 && hull[1].eval(x) <= hull[0].eval(x))
            hull.pop_front();
        return hull.front().eval(x);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<long long> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];
    sort(a.begin() + 1, a.end());

    const long long INF = (1LL << 62);
    vector<long long> prev(N + 1, 0), cur(N + 1, INF);

    for (int g = 1; g <= K; ++g) {
        fill(cur.begin(), cur.end(), INF);
        CHT hull;
        long long bestCompletedPair = INF;
        long long previousPairCost = INF;

        for (int t = 1; t <= N; ++t) {
            int i = t - 1;
            if (i >= 1 && prev[i - 1] != INF) {
                hull.add({-2 * a[i], prev[i - 1] + a[i] * a[i]});
            }

            long long pairCost = INF;
            if (!hull.hull.empty())
                pairCost = hull.query(a[t]) + a[t] * a[t];

            bestCompletedPair = min(bestCompletedPair, previousPairCost);
            cur[t] = min(cur[t - 1], bestCompletedPair);
            previousPairCost = pairCost;
        }

        prev.swap(cur);
    }

    cout << prev[N] << '\n';
    return 0;
}
